import { readFile, writeFile } from "node:fs/promises";
import sharp from "sharp";

// SVG paths are the source of truth. Raster outputs exist only for icon formats
// that require them; neither the concept preview nor its PNG layers are shipped.
const root = new URL("../", import.meta.url);
const svg = await readFile(new URL("public/rxcode-icon.svg", root));
await writeFile(new URL("app/icon.svg", root), svg);
await sharp(svg).resize(180, 180).png().toFile(new URL("app/apple-icon.png", root).pathname);
await writeFile(
  new URL("app/lib/brand-icon.ts", root),
  '// Generated by scripts/generate-brand-assets.mjs from public/rxcode-icon.svg.\n' +
    `export const BRAND_ICON_DATA_URL = "data:image/svg+xml;base64,${svg.toString("base64")}";\n`,
);

const sizes = [16, 32, 48, 64];
const frames = await Promise.all(
  sizes.map((size) => sharp(svg).resize(size, size).ensureAlpha().png().toBuffer()),
);
const header = Buffer.alloc(6 + sizes.length * 16);
header.writeUInt16LE(1, 2);
header.writeUInt16LE(sizes.length, 4);
let offset = header.length;
frames.forEach((frame, index) => {
  const entry = 6 + index * 16;
  header[entry] = sizes[index];
  header[entry + 1] = sizes[index];
  header.writeUInt16LE(1, entry + 4);
  header.writeUInt16LE(32, entry + 6);
  header.writeUInt32LE(frame.length, entry + 8);
  header.writeUInt32LE(offset, entry + 12);
  offset += frame.length;
});
await writeFile(new URL("app/favicon.ico", root), Buffer.concat([header, ...frames]));
